using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Web.Script.Serialization;
class HostSecurityTests {
 static List<string> checks=new List<string>();static void Check(bool v,string n){if(!v)throw new Exception(n);checks.Add(n);}static bool Reject(Action a){try{a();return false;}catch{return true;}}
 static void Main(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);string doc="https://jagolibrary.example/index.html";
 foreach(string good in new[]{doc,doc+"#board","https://JAGOLIBRARY.example/index.html"})Check(JagoHostSecurity.Trusted(good,doc),"trusted app "+good);
 foreach(string bad in new[]{"https://jagolibrary.example/other.html","https://jagolibrary.example/preview/import.svg","https://jagolibrary.example.evil/index.html","https://jagolibrary.example:8443/index.html","http://jagolibrary.example/index.html","https://user@jagolibrary.example/index.html",doc+"?file=other","data:text/html,hi","javascript:alert(1)","about:blank",null,""})Check(!JagoHostSecurity.Trusted(bad,doc),"reject foreign document "+bad);
 string local=new Uri(Path.Combine(root,"Jago-Pulse.html")).AbsoluteUri;Check(JagoHostSecurity.Trusted(local+"#x",local),"local main document");Check(!JagoHostSecurity.Trusted(new Uri(Path.Combine(root,"untrusted.html")).AbsoluteUri,local),"reject sibling local document");Check(!JagoHostSecurity.Trusted("file://other-host/share/Jago-Pulse.html",local),"reject UNC document");
 string file=Path.Combine(root,"document.json");File.WriteAllText(file,"{\"name\":\"normal\"}");Check(JagoHostSecurity.ReadBounded(file,100).Contains("normal"),"bounded read valid");Check(Reject(()=>JagoHostSecurity.ReadBounded(file,4)),"oversized read rejected");File.WriteAllText(file,"({});globalThis.compromised=true;//");Check(Reject(()=>JagoHostSecurity.JsonArgument(file,1000)),"executable recovery rejected as JSON");
 File.WriteAllText(file,"{\"name\":\");globalThis.compromised=true;//\",\"__proto__\":{\"polluted\":true}}");File.WriteAllText(Path.Combine(root,"argument.js"),JagoHostSecurity.JsonArgument(file,1000));Check(File.ReadAllText(Path.Combine(root,"argument.js")).StartsWith("JSON.parse("),"JSON passed as quoted data");
 JagoHostSecurity.Atomic(file,"{\"value\":1}");Check(File.ReadAllText(file)=="{\"value\":1}","atomic replace succeeds");using(var hold=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.None)){Check(Reject(()=>JagoHostSecurity.Atomic(file,"broken")),"failed replacement reported");}Check(File.ReadAllText(file)=="{\"value\":1}","failed replacement preserves original");Check(Directory.GetFiles(root,"*.tmp").Length==0,"failed replacement cleans temporary data");
 Parallel.For(0,30,i=>JagoHostSecurity.Atomic(file,"{\"value\":"+i+"}"));Check(new JavaScriptSerializer().Deserialize<Dictionary<string,int>>(File.ReadAllText(file)).ContainsKey("value"),"concurrent atomic writes leave complete JSON");
 File.WriteAllText(Path.Combine(root,"result.json"),new JavaScriptSerializer().Serialize(new{ok=true,checks=checks}));Console.WriteLine(checks.Count+" host security/recovery checks passed");}
}
